INSERT INTO public.commentprofile (comment, score, id_user) SELECT 'Buen manejo de Angular, el catálogo está muy bien organizado.', 5, (SELECT id FROM public."user" WHERE username = 'ana.torres') WHERE NOT EXISTS (SELECT 1 FROM public.commentprofile WHERE comment = 'Buen manejo de Angular, el catálogo está muy bien organizado.' AND id_user = (SELECT id FROM public."user" WHERE username = 'ana.torres'));
